inline void DrawEmblemSmall(cheeko::Display& d, int ox, int oy) {
  for (int i = 0; i < kEMBLEM_SMALL_RUNS; ++i) {
    const uint16_t* r = kEMBLEM_SMALL_RUN_DATA[i];
    d.FillRect(ox + r[1], oy + r[0], r[2], 1, kEMBLEM_SMALL_PALETTE[r[3]]);
  }
}
